    bronze_glasskilnspy = { name = "Bronast opazovalna odprtina peči", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast opazovalna odprtina peči za steklarje." },
    silver_glasskilnspy = { name = "Srebrn opazovalna odprtina peči", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn opazovalna odprtina peči za steklarje." },
