    sovereign_glasskilnspy_palace = { name = "Suverena glasskilnspy palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassKilnSpyMaker.ironStock=14; GlassKilnSpyMaker.bronzeStock=12; GlassKilnSpyMaker.woodStock=14; GlassKilnSpyMaker.leatherStock=8; GlassKilnSpyMaker.silverStock=8; GlassKilnSpyMaker.goldStock=6; GlassKilnSpyMaker.jewelStock=4; GlassKilnSpyMaker.pearlStock=4
GlassKilnSpyMaker.productStock = {}; GlassKilnSpyMaker.buildings = {}; GlassKilnSpyMaker.maker = nil; GlassKilnSpyMaker.activeMaking = {}; GlassKilnSpyMaker.totalProducts = 0; GlassKilnSpyMaker.dayTimer = 0
function GlassKilnSpyMaker.init() GlassKilnSpyMaker.ironStock=14; GlassKilnSpyMaker.bronzeStock=12; GlassKilnSpyMaker.woodStock=14; GlassKilnSpyMaker.leatherStock=8; GlassKilnSpyMaker.silverStock=8; GlassKilnSpyMaker.goldStock=6; GlassKilnSpyMaker.jewelStock=4; GlassKilnSpyMaker.pearlStock=4; GlassKilnSpyMaker.productStock={}; GlassKilnSpyMaker.buildings={}; GlassKilnSpyMaker.maker=nil; GlassKilnSpyMaker.activeMaking={}; GlassKilnSpyMaker.totalProducts=0; GlassKilnSpyMaker.dayTimer=0; print("[GlassKilnSpyMaker] Royal Glass Kiln Spy Maker System initialized (6 products, 4 buildings)") end
function GlassKilnSpyMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassKilnSpyMaker.maker={name=n or ("Opazovalnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Opazovalnik najet: %s (spretnost: %d)",GlassKilnSpyMaker.maker.name,s),"success") end; return true end
function GlassKilnSpyMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassKilnSpyMaker.build(id) local ok,e=GlassKilnSpyMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassKilnSpyMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassKilnSpyMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassKilnSpyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassKilnSpyMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassKilnSpyMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassKilnSpyMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassKilnSpyMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassKilnSpyMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassKilnSpyMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassKilnSpyMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassKilnSpyMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassKilnSpyMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassKilnSpyMaker.buildings==0 then return false,"Potrebna opazovalna delavnica" end; if not GlassKilnSpyMaker.maker then return false,"Potreben opazovalnik" end; return true end
function GlassKilnSpyMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassKilnSpyMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassKilnSpyMaker.ironStock=GlassKilnSpyMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassKilnSpyMaker.bronzeStock=GlassKilnSpyMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassKilnSpyMaker.woodStock=GlassKilnSpyMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassKilnSpyMaker.leatherStock=GlassKilnSpyMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassKilnSpyMaker.silverStock=GlassKilnSpyMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassKilnSpyMaker.goldStock=GlassKilnSpyMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassKilnSpyMaker.jewelStock=GlassKilnSpyMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassKilnSpyMaker.pearlStock=GlassKilnSpyMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassKilnSpyMaker.maker then t=math.max(1,t-math.floor(GlassKilnSpyMaker.maker.skill/13)) end; table.insert(GlassKilnSpyMaker.activeMaking,{id="glasskilnspy_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassKilnSpyMaker.completeMaking(m) local q=1.0+(GlassKilnSpyMaker.getQualityBonus()/100); if GlassKilnSpyMaker.maker then q=q+(GlassKilnSpyMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnSpyMaker.productStock[m.productType]=(GlassKilnSpyMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnSpyMaker.totalProducts=GlassKilnSpyMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnSpyMaker.maker then GlassKilnSpyMaker.maker.itemsMade=GlassKilnSpyMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnSpyMaker.maker.skill=math.min(100,GlassKilnSpyMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Opazovalnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilnspy.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassKilnSpyMaker.update(dt) if not _G.state then return end; GlassKilnSpyMaker.dayTimer=GlassKilnSpyMaker.dayTimer+dt; if GlassKilnSpyMaker.dayTimer>=30 then GlassKilnSpyMaker.dayTimer=0; for i=#GlassKilnSpyMaker.activeMaking,1,-1 do local m=GlassKilnSpyMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnSpyMaker.completeMaking(m); table.remove(GlassKilnSpyMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnSpyMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnSpyMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassKilnSpyMaker.getStats() return {ironStock=GlassKilnSpyMaker.ironStock,bronzeStock=GlassKilnSpyMaker.bronzeStock,woodStock=GlassKilnSpyMaker.woodStock,leatherStock=GlassKilnSpyMaker.leatherStock,silverStock=GlassKilnSpyMaker.silverStock,goldStock=GlassKilnSpyMaker.goldStock,jewelStock=GlassKilnSpyMaker.jewelStock,pearlStock=GlassKilnSpyMaker.pearlStock,productStock=GlassKilnSpyMaker.productStock,numBuildings=#GlassKilnSpyMaker.buildings,hasMaker=GlassKilnSpyMaker.maker~=nil,makerName=GlassKilnSpyMaker.maker and GlassKilnSpyMaker.maker.name or "—",makerSkill=GlassKilnSpyMaker.maker and GlassKilnSpyMaker.maker.skill or 0,activeMaking=#GlassKilnSpyMaker.activeMaking,totalProducts=GlassKilnSpyMaker.totalProducts} end
